  final_data <- rbindlist(dataset_list, fill = TRUE)
  out_file_rds <- file.path(OUTPUT_DIR, 'rq001_analytical_dataset.rds')
  out_file_csv <- file.path(OUTPUT_DIR, 'rq001_analytical_dataset.csv')
  saveRDS(final_data, out_file_rds)
  fwrite(head(final_data, 1000), out_file_csv) # sample preview
  message(sprintf('>> SUCCESS: Extracted %d rows across %d year(s). Saved to %s', nrow(final_data), length(dataset_list), out_file_rds))
} else {
  message('>> NOTICE: No local raw files found to extract. Download missing files from Google Drive first.')
}

